import 'package:flutter/material.dart';
import '../models/expense_audit_entry.dart';
import 'expense_formatters.dart';
String expenseAuditFieldLabel(String field){switch(field){case'title':return'Title';case'notes':return'Notes';case'amount':return'Amount';case'workerName':return'Worker';case'pricePerKg':return'Price per kg';case'chickenLines':return'Chicken lines';case'lineItems':return'Items';case'voided':return'Status';default:return field;}}
String formatExpenseAuditValue(String field,Object? value){if(value==null)return'—';if(field=='voided'&&value is bool)return value?'Voided':'Active';if((field=='amount'||field=='pricePerKg')&&value is num)return'Rs. ${formatExpenseNumber(value)}';if(field=='chickenLines'&&value is List){if(value.isEmpty)return'—';return value.map((x){final m=x as Map;return'${m['quantityKg']} kg ${m['chickenType']}';}).join(', ');}if(field=='lineItems'&&value is List){if(value.isEmpty)return'—';return value.map((x){final m=x as Map;return'${m['itemName']} (Rs. ${formatExpenseNumber(m['price'] as num)})';}).join(', ');}final t=value.toString();return t.isEmpty?'—':t;}
class ExpenseAuditTrail extends StatelessWidget{final List<ExpenseAuditEntry> entries;const ExpenseAuditTrail({super.key,required this.entries});@override Widget build(BuildContext context){if(entries.isEmpty)return const Padding(padding:EdgeInsets.symmetric(vertical:8),child:Text('No changes recorded.',key:Key('audit_trail_empty')));return Column(children:[for(var i=0;i<entries.length;i++)_Row(key:Key('audit_entry_$i'),entry:entries[i])]);}}
class _Row extends StatelessWidget{final ExpenseAuditEntry entry;const _Row({super.key,required this.entry});@override Widget build(BuildContext context){final when=entry.timestamp;return Container(width:double.infinity,padding:const EdgeInsets.symmetric(horizontal:16,vertical:12),decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(12),border:Border.all(color:const Color(0xFFD4AF37).withValues(alpha:.35))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text(expenseAuditFieldLabel(entry.field),style:const TextStyle(fontWeight:FontWeight.w700)),if(when!=null)Text('${formatExpenseDay(when)} • ${formatExpenseTime(when)}')]),const SizedBox(height:4),Text('${formatExpenseAuditValue(entry.field,entry.oldValue)} → ${formatExpenseAuditValue(entry.field,entry.newValue)}'),if(entry.changeReason.trim().isNotEmpty)Text('Reason: ${entry.changeReason}') ]));}}
